/// <summary>
/// Extension of SysTableLookup class
/// </summary>
[ExtensionOf(classStr(SysTableLookup))]
public final class AVASysTableLookupCls_Extension
{
    private const str SysGenFieldPrefix = 'SysGen_';
    private Map tableFieldOrderMap = new Map(Types::Integer, Types::Integer);

}

Method.Source:
/// <summary>
/// Build grid extension
/// </summary>
/// <param name = "_formBuildGridControl">The FormBuildGridControl</param>
/// <param name = "_formBuildDataSource">The FormBuildSource</param>
/// <returns>The updated FormBuildGridControl</returns>
protected FormBuildGridControl buildGrid
(
    FormBuildGridControl _formBuildGridControl,
    FormBuildDataSource  _formBuildDataSource
)
{
    next buildGrid(_formBuildGridControl, _formBuildDataSource);

    for (int itemNo = 1; itemNo <= conlen(lookupItems); itemNo++)
    {
        int fieldId;
        boolean returnItem;
        str method;
        boolean uiHidden;

        if (conLen(conpeek(lookupItems, itemNo)) == 4)
        {
            [fieldId, returnItem, method, uiHidden] = conpeek(lookupItems, itemNo);

            if (fieldId && uiHidden)
            {
                FieldName fieldName = fieldId2name(_formBuildDataSource.table(), fieldId);
                FormControlName formControlName = strFmt('%1%2', SysTableLookup::SysGenFieldPrefix, fieldName);

                for (int ctlNo = 1; ctlNo <= _formBuildGridControl.controlCount(); ctlNo++)
                {
                    FormBuildControl formBuildControl = _formBuildGridControl.controlNum(ctlNo) as FormBuildControl;

                    if (formBuildControl && formBuildControl.name() == formControlName)
                    {
                        formBuildControl.visible(!uiHidden);
                        break;
                    }
                }
            }
        }
    }

    return _formBuildGridControl;
}

/// <summary>
/// Adds a lookup field but hide it from the UI
/// </summary>
/// <param name = "_fieldId">The field ID</param>
/// <param name = "_returnItem">true if the field value should be returned otherwise false</param>
void addHiddenfield(FieldId _fieldId, boolean _returnItem = false)
{
    if (_fieldId)
    {
        this.addHiddenControl(_fieldId, _returnItem, '');
    }
}

/// <summary>
/// Adds a lookup control but hide it from the UI
/// </summary>
/// <param name = "_fieldId">The field ID</param>
/// <param name = "_returnItem">true if the field value should be returned otherwise false</param>
/// <param name = "_methodName">The method name</param>
void addHiddenControl(FieldId _fieldId, boolean _returnItem, str _methodName)
{
    this.addHiddenControl_Internal(_fieldId, _returnItem, _methodName);
}

/// <summary>
/// Adds a lookup control but hide it from the UI
/// </summary>
/// <param name = "_fieldId">The field ID</param>
/// <param name = "_returnItem">true if the field value should be returned otherwise false</param>
/// <param name = "_methodName">The method name</param>
private void addHiddenControl_Internal(fieldId _fieldId, boolean _returnItem, str _methodName)
{
    lookupItems += [[_fieldId, _returnItem, _methodName, true]];
}

/// <summary>
/// Add field order
/// </summary>
/// <param name = "_tableId">The table id</param>
/// <param name = "_fieldId">The field id</param>
void addFieldOrder(TableId _tableId, FieldId _fieldId)
{
    tableFieldOrderMap.add(_tableId, _fieldId);
}

/// <summary>
/// Add source field order
/// </summary>
/// <param name = "formRun">The form run</param>
void addDataSourceFilter(FormRun formRun)
{
    FormDataSource formDataSource = formRun.dataSource();

    if (tableFieldOrderMap && tableFieldOrderMap.elements() > 0)
    {
        // Set the field order
        MapEnumerator mapETor = tableFieldOrderMap.getEnumerator();

        while (mapETor.moveNext())
        {
            TableId tableId = mapETor.currentKey();
            FieldId fieldId = mapEtor.currentValue();

            if (formDataSource.table() == tableId && formDataSource.queryBuildDataSource())
            {
                formDataSource.queryBuildDataSource().addSortField(fieldId);
            }
        }
    }
}

/// <summary>
/// COC method for formRun
/// </summary>
/// <returns>The form run</returns>
protected FormRun formRun()
{
    FormRun formRun = next formRun();

    if (formRun)
    {
        this.addDataSourceFilter(formRun);
    }

    return formRun;
}
